def _read_drawable(r: Reader) -> m.Drawable:
    return m.Drawable(id=r.text(), runtime_id=r.text(), part_id=r.text(), raw_blend_mode=(integer(r.scalar('I')) if r.optional() else None), texture_asset_id=r.text(), texture_slot=integer(r.scalar('i')), renderable=r.boolean(), positions=tuple(m.Vec2(x=number(v[0]), y=number(v[1])) for v in r.numeric('ff', r.count())), uvs=tuple(m.Vec2(x=number(v[0]), y=number(v[1])) for v in r.numeric('ff', r.count())), indices=cast('tuple[int, ...]', tuple(v[0] for v in r.numeric('I', r.count()))), draw_order=integer(r.scalar('i')), render_order=integer(r.scalar('i')), opacity=number(r.scalar('f')), multiply_color=cast('tuple[float, float, float, float]', tuple(v[0] for v in r.numeric('f', 4))), screen_color=cast('tuple[float, float, float, float]', tuple(v[0] for v in r.numeric('f', 4))), blend_mode=_read_blendmode(r), enabled=r.boolean(), visible=r.boolean(), double_sided=r.boolean(), inverted_mask=r.boolean(), masks=tuple(r.text() for _ in range(r.count())))

def _read_offscreenframe(r: Reader) -> m.OffscreenFrame:
    return m.OffscreenFrame(renderable=r.boolean(), id=r.text(), runtime_id=r.text(), owner_part_id=r.text(), parent_offscreen_id=(r.text() if r.optional() else None), render_order=integer(r.scalar('i')), opacity=number(r.scalar('f')), enabled=r.boolean(), blend_mode=integer(r.scalar('I')), flags=integer(r.scalar('B')), masks=tuple(r.text() for _ in range(r.count())), multiply_color=cast('tuple[float, float, float, float]', tuple(v[0] for v in r.numeric('f', 4))), screen_color=cast('tuple[float, float, float, float]', tuple(v[0] for v in r.numeric('f', 4))))

def _read_rendercommand(r: Reader) -> m.RenderCommand:
    tag=r.u32()
    if tag==0:
        return m.RenderCommandBeginOffscreen(offscreen_id=r.text())
    elif tag==1:
        return m.RenderCommandDrawMesh(mesh_id=r.text())
    elif tag==2:
        return m.RenderCommandEndOffscreen(offscreen_id=r.text())
    raise ValueError("Unknown binary RenderCommand variant")

def _read_evaluateddeformer(r: Reader) -> m.EvaluatedDeformer:
    return m.EvaluatedDeformer(id=r.text(), enabled=r.boolean(), points=tuple(m.Vec2(x=number(v[0]), y=number(v[1])) for v in r.numeric('ff', r.count())), rotation_axis=(_read_vec2(r) if r.optional() else None))

def _read_geometrydiagnostic(r: Reader) -> m.GeometryDiagnostic:
    return m.GeometryDiagnostic(kind=_read_geometrydiagnostickind(r), mesh_id=r.text(), triangle_index=(integer(r.scalar('Q')) if r.optional() else None))

def _read_geometrydiagnostickind(r: Reader) -> m.GeometryDiagnosticKind:
    tag=r.u32()
    if tag==0:
        return m.GeometryDiagnosticKind('SmallTriangle')
    elif tag==1:
        return m.GeometryDiagnosticKind('InconsistentWinding')
    elif tag==2:
        return m.GeometryDiagnosticKind('OutsideModelBounds')
    raise ValueError("Unknown binary GeometryDiagnosticKind variant")

def _read_meshsnapshot(r: Reader) -> Snapshot[meshes.Mesh]:
    return Snapshot(_read_sourceref(r), meshes.Mesh(id=r.text(), name=r.text(), geometry=_read_meshgeometry(r)))

def _read_sourceref(r: Reader) -> Source:
    tag=r.u32()
    runtime=str(UUID(bytes=bytes(r.take(16)))); session=integer(r.scalar("Q"))
    edit=None
    if tag==1:
        if str(UUID(bytes=bytes(r.take(16))))!=runtime: raise ValueError("Mixed source runtimes")
        edit=integer(r.scalar("Q"))
    elif tag!=0: raise ValueError("Unknown source variant")
    version=Version(integer(r.scalar("Q")),integer(r.scalar("Q")),integer(r.scalar("Q")))
    sequence=integer(r.scalar("Q")) if tag==1 else 0
    return Source(runtime,session,version,edit,sequence)

def _read_imagesnapshot(r: Reader) -> Snapshot[resources.Image]:
    return Snapshot(_read_sourceref(r), resources.Image(id=r.text(), name=r.text(), pixels=_read_imagepixels(r)))

def _read_imagepixels(r: Reader) -> resources.ImagePixels:
    return resources.ImagePixels(width=integer(r.scalar('I')), height=integer(r.scalar('I')), rgba=r.bytes())

def encode_operations(operations: tuple[ops.WireOperation, ...]) -> bytes:
    if len(operations)>1024: raise ValueError("Too many authoring operations")
    w=Writer()
    w.raw(b"ZZA1"); w.raw(int(INPUT_SIGNATURE,16).to_bytes(16,"little")); w.u32(len(operations))
    for operation in operations:
        if isinstance(operation,m.OPERATION_TYPES):
            w.u32(0); _write_modelingcommand(operation,w)
        elif isinstance(operation,scene.OPERATION_TYPES):
            w.u32(1); _write_sceneoperation(operation,w)
        elif isinstance(operation,(ops.Create,ops.Rename,ops.SetPositions)):
            w.u32(4); _write_meshoperation(operation,w)
        elif isinstance(operation,ops.CreateParameter):
            w.u32(3); w.u32(0)
            _write_parametercreatespec(operation.spec, w)
        elif isinstance(operation,ops.PatchParameter):
            w.u32(3); w.u32(1)
            w.text(operation.id)
            _write_parameterpatch(operation.patch, w)
        elif isinstance(operation,ops.CreateMeshBinding):
            w.u32(2); w.u32(0)
            _write_meshbindingcreatespec(operation.spec, w)
        elif isinstance(operation,ops.SetMeshKeyform):
            w.u32(2); w.u32(1)
            w.text(operation.id)
            _write_meshkeyformspec(operation.keyform, w)
        elif isinstance(operation,ops.CreateImage):
            w.u32(5); w.u32(0)
            _write_imagecreatespec(operation, w)
            _write_imageid(operation.image._token, w)
        elif isinstance(operation,ops.ReplaceImage):
            w.u32(5); w.u32(1)
            w.text(operation.id)
            _write_imageid(operation.image._token, w)
        elif isinstance(operation,ops.RenameImage):
            w.u32(5); w.u32(2)
            w.text(operation.id)
            w.text(operation.name)
            if operation.expected_name is None:
                w.raw(b"\0")
            else:
                w.raw(b"\1")
                w.text(operation.expected_name)
        elif isinstance(operation,ops.ApplyPlan):
            w.u32(5); w.u32(3)
            _write_planid(operation.plan._token, w)
        else:
            raise TypeError("Expected typed authoring operation")
    return bytes(w.data)

def decode_records(value: bytes, signature: str) -> m.OwnedModelingRecords:
    if signature!=OUTPUT_SIGNATURE: raise ValueError("Binary record contract differs")
    r=Reader(value)
    result=_read_ownedmodelingrecords(r)
    r.finish()
    return result

def decode_samples(value: bytes, signature: str) -> m.ModelingSamples:
    if signature!=SAMPLE_SIGNATURE: raise ValueError("Binary sample contract differs")
    r=Reader(value)
    result=_read_modelingsamples(r)
    r.finish()
    return result

def decode_meshes(value: bytes,signature:str)->tuple[Snapshot[meshes.Mesh],...]:
    if signature!=MESH_SIGNATURE: raise ValueError("Binary mesh contract differs")
    r=Reader(value)
    result=tuple(_read_meshsnapshot(r) for _ in range(r.count()))
    r.finish()
    return result

def decode_bindings(value:bytes,signature:str)->tuple[m.MeshBinding,...]:
    if signature!=BINDING_SIGNATURE: raise ValueError("Binary binding contract differs")
    r=Reader(value)
    result=tuple(_read_meshbinding(r) for _ in range(r.count()))
    r.finish()
    return result

def decode_images(value:bytes,signature:str)->tuple[Snapshot[resources.Image],...]:
    if signature!='fbafcb840850220e3314b16301323be6': raise ValueError("Binary image contract differs")
    r=Reader(value)
    result=tuple(_read_imagesnapshot(r) for _ in range(r.count()))
    r.finish()
    return result
